// ==UserScript==
// @name         Gemini NanoBanana Watermark Remover Light
// @namespace    https://gist.github.com/Bl0ck154
// @version      0.3.0
// @description  Lightweight download-focused Gemini remover with standalone maps, v2 profile support and confidence-gated matching
// @icon         https://www.google.com/s2/favicons?domain=gemini.google.com
// @author       Bl0ck154
// @license      MIT
// @match        https://gemini.google.com/*
// @match        https://business.gemini.google/*
// @grant        unsafeWindow
// @grant        GM_registerMenuCommand
// @grant        GM_getValue
// @grant        GM_setValue
// @run-at       document-start
// @downloadURL  https://raw.githubusercontent.com/Bl0ck154/gemini-watermark-remover-light/main/gemini-watermark-remover-light.user.js
// @updateURL    https://raw.githubusercontent.com/Bl0ck154/gemini-watermark-remover-light/main/gemini-watermark-remover-light.user.js
// ==/UserScript==

(() => {
  "use strict";

  const LOG_PREFIX = "[Gemini Watermark Light]";
  const OUTPUT_KEY = "__gwr_light_output_format__";
  const OUTPUT_AUTO = "auto";
  const OUTPUT_COMPACT_PNG = "compact-png";
  const OUTPUT_JPEG = "jpeg-92";
  const OUTPUT_PNG = "png";
  const OUTPUT_OPTIONS = Object.freeze([
    {
      value: OUTPUT_AUTO,
      title: "Browser auto - compression ON",
      description: "Firefox uses JPG quality 92%. Chrome/Chromium uses a compact PNG wrapper with JPEG 92% bytes. Recommended."
    },
    {
      value: OUTPUT_COMPACT_PNG,
      title: "Compact PNG wrapper - compression ON",
      description: "Saves as .png, but stores JPEG 92% bytes inside to keep files small and avoid .jfif on Chromium."
    },
    {
      value: OUTPUT_JPEG,
      title: "Normal JPG 92 - compression ON",
      description: "Standard JPEG output. Small files, but Chromium on Windows may save .jfif in some flows."
    },
    {
      value: OUTPUT_PNG,
      title: "True PNG - compression OFF",
      description: "Lossless PNG output. Largest files, but no JPEG compression."
    }
  ]);
  const JPEG_MIME = "image/jpeg";
  const PNG_MIME = "image/png";
  const JPEG_QUALITY = 0.92;
  const ALPHA_NOISE_FLOOR = 3 / 255;
  const ALPHA_THRESHOLD = 2e-3;
  const MAX_ALPHA = 0.99;
  const PROCESSED_BLOB_TTL_MS = 120000;
  const DOWNLOAD_INTENT_WINDOW_MS = 30 * 60 * 1000;
  const MIN_MULTI_CANDIDATE_SCORE = 0.002;
  const MIN_MULTI_SCORE_GAP = 0.0005;
  const MIN_SCAN_EDGE = 1536;
  const SCAN_MARGIN_MIN = 32;
  const SCAN_MARGIN_MAX = 384;
  const SCAN_MARGIN_STEP = 16;
  const MIN_SCAN_CANDIDATE_SCORE = 0.004;
  const MIN_SCAN_SCORE_GAP = 0.001;
  const mapPromises = new Map();
  // Quantized calibrated alpha maps. The original Float32 values were exact
  // 8-bit fractions, so storing one byte per pixel is lossless here.
  const EMBEDDED_ALPHA_MAPS_U8 = Object.freeze({
    "36-v2": "",
    "24-preview": "",
    48: "",
    96: "",
    "96-20260520": ""
  });
  const processedCache = new Map();
  const processedBlobSignatures = new Map();
  let downloadIntentUntil = 0;
  const HALF_K_SIZE_KEYS = new Set([
    "512x512", "256x1024", "192x1536", "424x632", "632x424", "448x600", "600x448",
    "1024x256", "464x576", "576x464", "1536x192", "384x688", "688x384", "792x168"
  ]);
  const ONE_K_SIZE_KEYS = new Set([
    "1024x1024", "512x2048", "384x3072", "848x1264", "1264x848", "896x1200", "2048x512",
    "1200x896", "928x1152", "1152x928", "3072x384", "768x1376", "1376x768", "1408x768",
    "1584x672", "832x1248", "1248x832", "864x1184", "1184x864", "768x1344", "1344x768",
    "1536x672"
  ]);
  const DOWNLOAD_ACTION_PATTERN = /(download|завантаж|скач|下载|下載|descargar|telecharger|télécharger|herunterladen|scarica|다운로드)/i;

  function getValue(key, fallback) {
    try {
      return typeof GM_getValue === "function" ? GM_getValue(key, fallback) : localStorage.getItem(key) ?? fallback;
    } catch {
      return fallback;
    }
  }

  function setValue(key, value) {
    try {
      if (typeof GM_setValue === "function") GM_setValue(key, value);
      else localStorage.setItem(key, value);
    } catch {}
  }

  function isFirefox() {
    return /firefox|librewolf|waterfox/i.test(navigator.userAgent || "");
  }

  function getOutputPreference() {
    const value = getValue(OUTPUT_KEY, OUTPUT_AUTO);
    return [OUTPUT_AUTO, OUTPUT_COMPACT_PNG, OUTPUT_JPEG, OUTPUT_PNG].includes(value) ? value : OUTPUT_AUTO;
  }

  function resolveOutputFormat() {
    const value = getOutputPreference();
    return value === OUTPUT_AUTO ? (isFirefox() ? OUTPUT_JPEG : OUTPUT_COMPACT_PNG) : value;
  }

  function getOutputLabel(value = getOutputPreference()) {
    if (value === OUTPUT_AUTO) return `Browser auto (${getOutputLabel(resolveOutputFormat())})`;
    return OUTPUT_OPTIONS.find((option) => option.value === value)?.title || "Browser auto";
  }

  function selectOutput(value) {
    setValue(OUTPUT_KEY, value);
    location.reload();
  }

  function openSettingsPrompt() {
    const current = getOutputPreference();
    const lines = OUTPUT_OPTIONS.map((option, index) => `${index + 1}. ${option.value === current ? "✓ " : ""}${option.title}\n   ${option.description}`);
    const answer = prompt(`Gemini Watermark Light settings\n\nChoose output/compression mode:\n\n${lines.join("\n\n")}\n\nEnter 1-${OUTPUT_OPTIONS.length}:`, String(Math.max(1, OUTPUT_OPTIONS.findIndex((option) => option.value === current) + 1)));
    if (answer === null) return;
    const index = Number.parseInt(String(answer).trim(), 10) - 1;
    const selected = OUTPUT_OPTIONS[index];
    if (!selected) {
      alert("Invalid Light setting. Open the menu and choose a number from the list.");
      return;
    }
    selectOutput(selected.value);
  }

  function registerMenu() {
    if (typeof GM_registerMenuCommand !== "function") return;
    GM_registerMenuCommand(`Light Settings... current: ${getOutputLabel()}`, openSettingsPrompt);
    for (const option of OUTPUT_OPTIONS) {
      GM_registerMenuCommand(`${option.value === getOutputPreference() ? "✓ " : "Set: "}${option.title}`, () => selectOutput(option.value));
    }
  }

  async function getAlphaMap(key) {
    if (!mapPromises.has(key)) {
      const promise = Promise.resolve().then(() => {
        const packed = EMBEDDED_ALPHA_MAPS_U8[key];
        if (!packed) throw new Error(`Missing embedded alpha map: ${key}`);
        const binary = atob(packed);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        const expectedLength = Number.parseInt(key, 10) ** 2;
        if (bytes.length !== expectedLength) throw new Error(`Invalid embedded alpha map: ${key}`);
        return Float32Array.from(bytes, (value) => value / 255);
      }).catch((error) => {
        mapPromises.delete(key);
        throw error;
      });
      mapPromises.set(key, promise);
    }
    return mapPromises.get(key);
  }

  function isGoogleusercontentHost(hostname) {
    return hostname === "googleusercontent.com" || hostname.endsWith(".googleusercontent.com");
  }

  function classifyGeminiAssetPath(pathname) {
    const first = String(pathname || "").split("/").filter(Boolean)[0] || "";
    if (first.startsWith("rd-")) {
      const variant = first.slice(3);
      return { isPreview: false, isDownload: variant.endsWith("-dl") };
    }
    if (first === "gg") return { isPreview: true, isDownload: false };
    if (!first.startsWith("gg-")) return null;
    const variant = first.slice(3);
    const isDownload = variant === "dl" || variant.endsWith("-dl");
    return { isPreview: !isDownload, isDownload };
  }

  function classifyGeminiAssetUrl(url) {
    try {
      const parsed = new URL(url);
      return isGoogleusercontentHost(parsed.hostname) ? classifyGeminiAssetPath(parsed.pathname) : null;
    } catch {
      return null;
    }
  }

  function hasNativeDownloadToken(pathname) {
    return /(?:^|[=-])d(?:-I)?(?:-[A-Za-z]+)*$/i.test(String(pathname || ""));
  }

  function isExplicitDownloadAssetUrl(url) {
    try {
      const parsed = new URL(url);
      const asset = classifyGeminiAssetUrl(url);
      return Boolean(asset && (asset.isDownload === true || hasNativeDownloadToken(parsed.pathname)));
    } catch {
      return false;
    }
  }

  function isPotentialOriginalAssetUrl(url) {
    return classifyGeminiAssetUrl(url)?.isPreview === false;
  }

  function hasRecentDownloadIntent() {
    return Date.now() <= downloadIntentUntil;
  }

  function shouldProcessGeminiFetchUrl(url) {
    if (isExplicitDownloadAssetUrl(url)) return true;
    return isPotentialOriginalAssetUrl(url) && hasRecentDownloadIntent();
  }

  function normalizeGoogleusercontentImageUrl(url) {
    if (!classifyGeminiAssetUrl(url)) return url;
    try {
      const parsed = new URL(url);
      const path = parsed.pathname;
      if (/=w\d+-h\d+([^/]*)$/i.test(path)) parsed.pathname = path.replace(/=w\d+-h\d+([^/]*)$/i, "=s0$1");
      else if (hasNativeDownloadToken(path) && !/=s0(?:-[^/]*)?$/i.test(path)) parsed.pathname = path.replace(/=(?:d|d-I)$/i, (match) => `=s0-${match.slice(1)}`);
      else if (/=(?:s|w|h)\d+([^/]*)$/i.test(path)) parsed.pathname = path.replace(/=(?:s|w|h)\d+([^/]*)$/i, "=s0$1");
      else parsed.pathname = `${path}=s0`;
      return parsed.toString();
    } catch {
      return url;
    }
  }

  function getV2SmallConfig(width, height) {
    const longSide = Math.max(width, height);
    const shortSide = Math.min(width, height);
    if (longSide > 2048 || shortSide <= 0) return null;
    const sourceLongDim = shortSide >= 566 ? 2752 : (shortSide >= 550 ? 2816 : 2848);
    const margin = Math.round(192 * (longSide / sourceLongDim));
    const config = { size: 36, marginRight: margin, marginBottom: margin, mapKey: "36-v2" };
    return width - margin - config.size >= 0 && height - margin - config.size >= 0 ? config : null;
  }

  function appendUniqueCandidate(candidates, candidate) {
    if (!candidate) return candidates;
    const duplicate = candidates.some((item) => item.size === candidate.size && item.marginRight === candidate.marginRight && item.marginBottom === candidate.marginBottom && item.mapKey === candidate.mapKey);
    if (!duplicate) candidates.push(candidate);
    return candidates;
  }

  function getCandidateConfigs(width, height) {
    const key = `${width}x${height}`;
    const v2Small = getV2SmallConfig(width, height);

    if (HALF_K_SIZE_KEYS.has(key)) {
      return appendUniqueCandidate([{ size: 48, marginRight: 32, marginBottom: 32, mapKey: "48", prior: 0.00025 }], v2Small);
    }

    if (ONE_K_SIZE_KEYS.has(key)) {
      return appendUniqueCandidate([
        { size: 48, marginRight: 32, marginBottom: 32, mapKey: "48", prior: 0.00035 },
        { size: 48, marginRight: 96, marginBottom: 96, mapKey: "48", alphaGain: 0.55, prior: 0.00015 },
        { size: 96, marginRight: 64, marginBottom: 64, mapKey: "96" },
        { size: 24, marginRight: 48, marginBottom: 48, mapKey: "24-preview", alphaGain: 0.55 }
      ], v2Small);
    }

    if (Math.max(width, height) >= 1024) {
      const oldMargin = { size: 96, marginRight: 64, marginBottom: 64, mapKey: "96" };
      const newMargin = { size: 96, marginRight: 192, marginBottom: 192, mapKey: "96-20260520" };
      const currentLight = { size: 48, marginRight: 96, marginBottom: 96, mapKey: "48", alphaGain: 0.55 };
      const candidates = [oldMargin, currentLight];
      if (Math.max(width, height) <= 1800) {
        candidates.push(
          { size: 48, marginRight: 32, marginBottom: 32, mapKey: "48" },
          { size: 24, marginRight: 48, marginBottom: 48, mapKey: "24-preview", alphaGain: 0.55 }
        );
      }
      if (width - newMargin.marginRight - newMargin.size >= 0 && height - newMargin.marginBottom - newMargin.size >= 0) candidates.push(newMargin);
      return appendUniqueCandidate(candidates, v2Small);
    }

    return appendUniqueCandidate([{ size: 48, marginRight: 32, marginBottom: 32, mapKey: "48", trusted: true }], v2Small);
  }

  function scoreConfig(imageData, alphaMap, config) {
    const { width, height, data } = imageData;
    const x = width - config.marginRight - config.size;
    const y = height - config.marginBottom - config.size;
    if (x < 0 || y < 0) return Number.NEGATIVE_INFINITY;
    let alphaSum = 0;
    let weightedLum = 0;
    let lumSum = 0;
    let count = 0;
    for (let row = 0; row < config.size; row++) {
      for (let col = 0; col < config.size; col++) {
        const alpha = Math.max(0, alphaMap[row * config.size + col] - ALPHA_NOISE_FLOOR);
        const index = ((y + row) * width + x + col) * 4;
        const lum = (0.2126 * data[index] + 0.7152 * data[index + 1] + 0.0722 * data[index + 2]) / 255;
        lumSum += lum;
        count += 1;
        if (alpha >= ALPHA_THRESHOLD) {
          alphaSum += alpha;
          weightedLum += alpha * lum;
        }
      }
    }
    if (!alphaSum || !count) return Number.NEGATIVE_INFINITY;
    return weightedLum / alphaSum - lumSum / count;
  }

  async function selectConfig(imageData) {
    const candidates = getCandidateConfigs(imageData.width, imageData.height);
    if (candidates.length === 1 && candidates[0].trusted) return candidates[0];
    let best = candidates[0];
    let bestScore = Number.NEGATIVE_INFINITY;
    let secondBestScore = Number.NEGATIVE_INFINITY;
    for (const candidate of candidates) {
      const alphaMap = await getAlphaMap(candidate.mapKey);
      const score = scoreConfig(imageData, alphaMap, candidate) + (candidate.prior || 0);
      if (score > bestScore) {
        secondBestScore = bestScore;
        best = candidate;
        bestScore = score;
      } else if (score > secondBestScore) {
        secondBestScore = score;
      }
    }
    if (bestScore < MIN_MULTI_CANDIDATE_SCORE) return scanBottomRightConfig(imageData);
    if (Number.isFinite(secondBestScore) && bestScore - secondBestScore < MIN_MULTI_SCORE_GAP) return scanBottomRightConfig(imageData);
    return best;
  }

  async function scanBottomRightConfig(imageData) {
    const { width, height } = imageData;
    if (Math.min(width, height) < MIN_SCAN_EDGE) return null;
    let best = null;
    let bestScore = Number.NEGATIVE_INFINITY;
    let secondBestScore = Number.NEGATIVE_INFINITY;
    const profiles = [
      { mapKey: "24-preview", size: 24, alphaGain: 0.55 },
      { mapKey: "36-v2", size: 36 },
      { mapKey: "48", size: 48, alphaGain: 0.55 },
      { mapKey: "96", size: 96 },
      { mapKey: "96-20260520", size: 96 }
    ];
    for (const profile of profiles) {
      const alphaMap = await getAlphaMap(profile.mapKey);
      for (let marginRight = SCAN_MARGIN_MIN; marginRight <= SCAN_MARGIN_MAX; marginRight += SCAN_MARGIN_STEP) {
        for (let marginBottom = SCAN_MARGIN_MIN; marginBottom <= SCAN_MARGIN_MAX; marginBottom += SCAN_MARGIN_STEP) {
          const candidate = { ...profile, marginRight, marginBottom };
          const score = scoreConfig(imageData, alphaMap, candidate);
          if (score > bestScore) {
            secondBestScore = bestScore;
            bestScore = score;
            best = candidate;
          } else if (score > secondBestScore) {
            secondBestScore = score;
          }
        }
      }
    }
    if (bestScore < MIN_SCAN_CANDIDATE_SCORE) return null;
    if (bestScore - secondBestScore < MIN_SCAN_SCORE_GAP) return null;
    return best;
  }

  function removeWatermark(imageData, alphaMap, config) {
    const { width, height, data } = imageData;
    const x = width - config.marginRight - config.size;
    const y = height - config.marginBottom - config.size;
    if (x < 0 || y < 0) return;
    for (let row = 0; row < config.size; row++) {
      for (let col = 0; col < config.size; col++) {
        const imageIndex = ((y + row) * width + x + col) * 4;
        const rawAlpha = alphaMap[row * config.size + col];
        const alphaGain = config.alphaGain || 1;
        if (Math.max(0, rawAlpha - ALPHA_NOISE_FLOOR) * alphaGain < ALPHA_THRESHOLD) continue;
        const alpha = Math.min(rawAlpha * alphaGain, MAX_ALPHA);
        const remainder = 1 - alpha;
        for (let channel = 0; channel < 3; channel++) {
          data[imageIndex + channel] = Math.max(0, Math.min(255, Math.round((data[imageIndex + channel] - alpha * 255) / remainder)));
        }
      }
    }
  }

  function loadImage(blob) {
    return new Promise((resolve, reject) => {
      const objectUrl = URL.createObjectURL(blob);
      const image = new Image();
      image.onload = () => {
        URL.revokeObjectURL(objectUrl);
        resolve(image);
      };
      image.onerror = () => {
        URL.revokeObjectURL(objectUrl);
        reject(new Error("Failed to decode Gemini image"));
      };
      image.src = objectUrl;
    });
  }

  function canvasToBlob(canvas, type, quality) {
    return new Promise((resolve, reject) => canvas.toBlob(
      (blob) => blob ? resolve(blob) : reject(new Error("Failed to encode Gemini image")),
      type,
      quality
    ));
  }

  async function processBlob(blob) {
    const image = await loadImage(blob);
    const canvas = document.createElement("canvas");
    canvas.width = image.naturalWidth || image.width;
    canvas.height = image.naturalHeight || image.height;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    context.drawImage(image, 0, 0);
    const imageData = context.getImageData(0, 0, canvas.width, canvas.height);
    const config = await selectConfig(imageData);
    if (!config) throw new Error("No confident Gemini watermark match");
    removeWatermark(imageData, await getAlphaMap(config.mapKey), config);
    context.putImageData(imageData, 0, 0);
    const format = resolveOutputFormat();
    if (format === OUTPUT_PNG) return markProcessedBlob(await canvasToBlob(canvas, PNG_MIME));
    const jpeg = markProcessedBlob(await canvasToBlob(canvas, JPEG_MIME, JPEG_QUALITY));
    if (format !== OUTPUT_COMPACT_PNG) return jpeg;
    const wrapped = new Blob([jpeg], { type: PNG_MIME });
    markProcessedBlob(wrapped);
    Object.defineProperty(wrapped, "__gwrCompactPngWrapper", { value: true });
    return wrapped;
  }

  function buildRequestArgs(args, normalizedUrl) {
    const next = [...args];
    const input = next[0];
    const init = next[1];
    if (typeof input === "string") {
      next[0] = normalizedUrl;
    } else if (input && typeof input === "object" && typeof input.url === "string") {
      next[0] = new Request(new Request(normalizedUrl, input), { credentials: "omit" });
    } else {
      next[0] = normalizedUrl;
    }
    if (init && typeof init === "object") next[1] = { ...init, credentials: "omit" };
    return next;
  }

  function isImageResponse(response) {
    const type = response?.headers?.get?.("content-type") || "";
    return !type || /^image\//i.test(type);
  }

  function filenameForBlob(blob) {
    return blob?.__gwrCompactPngWrapper ? "gemini-image.png" : blob?.type === JPEG_MIME ? "gemini-image.jpg" : "gemini-image.png";
  }

  function blobSignature(blob) {
    return blob && typeof blob.size === "number" ? `${blob.type || ""}:${blob.size}` : "";
  }

  function rememberProcessedBlob(blob) {
    const signature = blobSignature(blob);
    if (!signature) return;
    processedBlobSignatures.set(signature, { filename: filenameForBlob(blob), expiresAt: Date.now() + PROCESSED_BLOB_TTL_MS });
    if (processedBlobSignatures.size > 128) processedBlobSignatures.delete(processedBlobSignatures.keys().next().value);
  }

  function consumeProcessedBlobFilename(blob) {
    if (blob?.__gwrLightProcessed === true) return filenameForBlob(blob);
    const signature = blobSignature(blob);
    const entry = signature ? processedBlobSignatures.get(signature) : null;
    if (!entry) return "";
    if (entry.expiresAt < Date.now()) {
      processedBlobSignatures.delete(signature);
      return "";
    }
    return entry.filename;
  }

  function markProcessedBlob(blob) {
    try {
      Object.defineProperty(blob, "__gwrLightProcessed", { value: true });
    } catch {}
    return blob;
  }

  function buildResponse(response, blob) {
    const headers = new Headers(response.headers);
    headers.delete("content-length");
    headers.delete("content-encoding");
    headers.set("content-type", blob?.__gwrCompactPngWrapper ? PNG_MIME : blob.type || PNG_MIME);
    const filename = filenameForBlob(blob);
    rememberProcessedBlob(blob);
    headers.set("content-disposition", `attachment; filename="${filename}"`);
    headers.set("x-content-type-options", "nosniff");
    return new Response(blob, { status: response.status, statusText: response.statusText, headers });
  }

  function rememberBlobUrl(url, blob) {
    if (!url?.startsWith?.("blob:")) return;
    const filename = consumeProcessedBlobFilename(blob);
    if (!filename) return;
    processedCache.set(url, filename);
    if (processedCache.size > 128) processedCache.delete(processedCache.keys().next().value);
  }

  function installBlobFilenameHook(targetWindow) {
    const urlApi = targetWindow.URL;
    const anchorProto = targetWindow.HTMLAnchorElement?.prototype;
    if (!urlApi?.createObjectURL || !anchorProto?.click) return;
    const originalCreateObjectURL = urlApi.createObjectURL.bind(urlApi);
    const originalRevokeObjectURL = urlApi.revokeObjectURL?.bind(urlApi);
    const originalClick = anchorProto.click;
    urlApi.createObjectURL = function createObjectURL(blob) {
      const url = originalCreateObjectURL(blob);
      rememberBlobUrl(url, blob);
      return url;
    };
    if (originalRevokeObjectURL) {
      urlApi.revokeObjectURL = function revokeObjectURL(url) {
        processedCache.delete(String(url || ""));
        return originalRevokeObjectURL(url);
      };
    }
    anchorProto.click = function click(...args) {
      const filename = processedCache.get(String(this.href || ""));
      if (filename) this.download = filename;
      return originalClick.apply(this, args);
    };
  }

  function installDownloadIntentHook(targetWindow) {
    targetWindow.document?.addEventListener?.("click", (event) => {
      const target = event.target?.closest?.("button,[role='button'],a") || event.target;
      const label = [target?.getAttribute?.("aria-label"), target?.getAttribute?.("title"), target?.textContent]
        .filter(Boolean)
        .join(" ");
      if (DOWNLOAD_ACTION_PATTERN.test(label)) downloadIntentUntil = Date.now() + DOWNLOAD_INTENT_WINDOW_MS;
    }, true);
  }

  function installFetchHook(targetWindow) {
    const originalFetch = targetWindow.fetch?.bind(targetWindow);
    if (typeof originalFetch !== "function") return;
    targetWindow.fetch = async function fetch(...args) {
      const input = args[0];
      const url = typeof input === "string" ? input : input?.url;
      if (!shouldProcessGeminiFetchUrl(url)) return originalFetch(...args);
      const isExplicitDownload = isExplicitDownloadAssetUrl(url);
      const normalizedUrl = normalizeGoogleusercontentImageUrl(url);
      const response = await originalFetch(...buildRequestArgs(args, normalizedUrl));
      if (!response?.ok || !isImageResponse(response)) return response;
      const fallback = response.clone?.();
      try {
        let pending = processedCache.get(normalizedUrl);
        if (!pending || typeof pending === "string") {
          pending = response.blob().then(processBlob).finally(() => {
            if (processedCache.get(normalizedUrl) === pending) processedCache.delete(normalizedUrl);
          });
          processedCache.set(normalizedUrl, pending);
        }
        const processedBlob = await pending;
        console.log(LOG_PREFIX, "processed download", canvasSizeLabel(processedBlob));
        return buildResponse(response, processedBlob);
      } catch (error) {
        console.warn(LOG_PREFIX, "download processing failed", error);
        return fallback || response;
      }
    };
  }

  function canvasSizeLabel(blob) {
    return blob?.size ? `${Math.round(blob.size / 1024)} KB` : "";
  }

  const targetWindow = typeof unsafeWindow !== "undefined" ? unsafeWindow : window;
  registerMenu();
  installBlobFilenameHook(targetWindow);
  installDownloadIntentHook(targetWindow);
  installFetchHook(targetWindow);
  console.log(LOG_PREFIX, `ready, output: ${getOutputLabel()}`);
})();
